+			if (RATE_IS_DSSS(phdr.data_rate)) {
+				/* 11b */
+				phdr.phy = PHDR_802_11_PHY_11B;
+			} else if (RATE_IS_OFDM(phdr.data_rate)) {
+				/* 11a or 11g, depending on the band. */
+				if (phdr.has_frequency) {
+					if (FREQ_IS_BG(phdr.frequency)) {
