+		} else if (phdr.phy == PHDR_802_11_PHY_11G) {
+			if (RATE_IS_DSSS(phdr.data_rate)) {
+				/* DSSS, so 11b. */
+				phdr.phy = PHDR_802_11_PHY_11B;
+			}
+		}
